), live as (
  select c.id, c.college, c.kind, c.read_run, c.course_code, c.source_url, c.lead, c.shape, c.fingerprint,
         c.fingerprint = md5(c.outcomes::text) as fp_ok
    from public.course_outcomes c join e using (id)
)
select json_build_object(
  'at', to_char(now() at time zone 'utc', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
  'listed', (select count(*) from e),
  'rows', (select count(*) from live),
  'guard_ok', (select count(*) from live where college = 'Golden West College' and kind = 'slo'
                 and read_run = '41399075269' and lead is null and fp_ok),
  'differ', coalesce((select json_agg(json_build_array(l.id, l.fingerprint, l.shape, l.lead is null) order by l.id)
                        from live l join e using (id)
                       where l.fingerprint <> e.fp or l.shape <> e.shape or l.lead is not null or not l.fp_ok), '[]'::json),
  'missing', coalesce((select json_agg(e.id order by e.id) from e where e.id not in (select id from live)), '[]'::json),
  'checksum', (select md5(string_agg(id || ':' || fingerprint || ':' || shape, ',' order by id)) from live),
  'after_taken', (select count(*) from e join live l using (id) join public.course_outcomes c
                     on c.college = l.college and c.kind = 'slo' and c.course_code = l.course_code
                    and c.source_url = l.source_url and c.fingerprint = e.after_fp and c.id <> l.id),
  'total_gw_slo', (select count(*) from public.course_outcomes where college = 'Golden West College' and kind = 'slo'));
